// Branded types
declare const UserIdBrand: unique symbol;
type userId = string & { readonly [UserIdBrand]: typeof UserIdBrand };

declare const PostIdBrand: unique symbol;
type postId = string & { readonly [PostIdBrand]: typeof PostIdBrand };


function deleteUserPost(userId: userId, postId: postId) {
    console.log(`Executing DELETE: User ${userId}, Post ${postId}`);
}

function validateUserId(id: string): userId {
    return id as userId;
}

function validatePostId(id: string): postId {
    return id as postId;
}

const incomingPostId = validatePostId("post_123");
const incomingUserId = validateUserId("user_123");

deleteUserPost(incomingUserId, incomingPostId);